package net.civeira.phylax.features.access.userinvitation.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.access.userinvitation.domain.UserInvitationStatusOptions;

class StatusVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property status of user invitation ")
  void test_status_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom("_PENDING_"));
    Assertions.assertEquals(UserInvitationStatusOptions.PENDING,
        StatusVO.tryFrom("PENDING").getStatus().orElse(null));
    Assertions.assertFalse(StatusVO.nullValue().getStatus().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(StatusVO.tryFrom(null).getStatus().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(UserInvitationStatusOptions.PENDING,
        StatusVO.from(UserInvitationStatusOptions.PENDING).getStatus().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + UserInvitationStatusOptions.PENDING + "]",
        StatusVO.from(UserInvitationStatusOptions.PENDING).toString());
  }
}
